+    fn handle_visual_key(&mut self, key: UiKey, right_content: &str) -> Vec<UiAction> {
+        match key {
+            UiKey::Esc => {
+                self.visual_selection = None;
+                Vec::new()
+            }
+            UiKey::Char('v') => {
+                self.start_visual_selection(VisualKind::Character, right_content);
+                Vec::new()
+            }
+            UiKey::Char('V') => {
+                self.start_visual_selection(VisualKind::Line, right_content);
+                Vec::new()
+            }
+            UiKey::Char(CTRL_V_CHAR) => {
+                self.start_visual_selection(VisualKind::Block, right_content);
+                Vec::new()
+            }
+            UiKey::Char('h') | UiKey::Left => {
+                self.move_visual_selection(0, -1, right_content);
+                Vec::new()
+            }
+            UiKey::Char('j') | UiKey::Down => {
+                self.move_visual_selection(1, 0, right_content);
+                Vec::new()
+            }
+            UiKey::Char('k') | UiKey::Up => {
+                self.move_visual_selection(-1, 0, right_content);
+                Vec::new()
+            }
+            UiKey::Char('l') | UiKey::Right => {
+                self.move_visual_selection(0, 1, right_content);
+                Vec::new()
+            }
+            UiKey::Char('y') => self.yank_visual_selection(right_content, false),
+            UiKey::Char('Y') => self.yank_visual_selection(right_content, true),
+            _ => Vec::new(),
+        }
+    }
+
+    fn move_visual_selection(
+        &mut self,
+        row_delta: isize,
+        column_delta: isize,
+        right_content: &str,
+    ) {
+        let Some(selection) = self.visual_selection else {
+            return;
+        };
+        let lines = self.visual_lines_for_focus(selection.focus, right_content);
+        let max_row = lines.len().saturating_sub(1);
+        let row = move_index(selection.cursor.row, row_delta, max_row);
+        let line_width = lines.get(row).map(|line| line.chars().count()).unwrap_or(0);
+        let max_column = line_width.saturating_sub(1);
+        let column = move_index(selection.cursor.column, column_delta, max_column);
+
+        if let Some(selection) = self.visual_selection.as_mut() {
+            selection.cursor = VisualPosition { row, column };
+        }
+    }
+
+    fn yank_visual_selection(&mut self, right_content: &str, force_linewise: bool) -> Vec<UiAction> {
+        let Some(selection) = self.visual_selection.take() else {
+            return Vec::new();
+        };
+        let lines = self.visual_lines_for_focus(selection.focus, right_content);
+        let text = selected_visual_text(&selection, &lines, force_linewise);
+        let char_count = text.chars().count();
+        self.clipboard = Some(text);
+        self.pending_clipboard.set(true);
+        self.show_status_notice(
+            format!("copied {char_count} chars"),
+            Duration::from_secs(STATUS_NOTICE_SECONDS),
+        );
+        Vec::new()
+    }

